/**
 * Fetches clients associated with the logged-in dietitian.
 */
export const fetchDietitianClients = async (): Promise<Client[]> => {
  try {
    const { data, error } = await supabase
      .from('clients')
      .select('*');

    if (error) {
      // Log as warning instead of error to reduce noise in development without backend
      console.warn('Supabase clients fetch failed, falling back to mock data:', error.message || error);
      return []; 
    }

    // Map Supabase DB shape to App UI shape
    return (data || []).map((dbClient: any) => ({
      id: dbClient.id,
      name: dbClient.name || dbClient.full_name || 'İsimsiz Danışan',
      email: dbClient.email || '',
      avatar: dbClient.avatar_url || USER_AVATAR,
      status: dbClient.status === 'active' ? 'Aktif' : 'Pasif',
      goal: dbClient.goal || 'Sağlıklı Yaşam',
      startDate: dbClient.start_date ? new Date(dbClient.start_date).toLocaleDateString('tr-TR') : '-',
      duration: dbClient.duration || '1 Ay',
      currentWeight: dbClient.current_weight ? `${dbClient.current_weight} kg` : '-',
      weeklyChange: dbClient.weekly_change || 0,
      compliance: dbClient.compliance_score || 0,
    }));
  } catch (err) {
    console.warn('Unexpected error in fetchDietitianClients, using fallback:', err);
    return [];
  }
};

