import { supabase } from '../../../lib/supabaseClient';
import { DietitianProfile } from '../../../shared/types';

export interface RegistrationData {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  phone: string;
  university: string;
  graduationYear: string;
  experienceYears: string;
  specialization: string;
  bio: string;
  diplomaFile: File;
}

/**
 * Handles the full registration flow:
 * 1. Sign up User (Auth)
 * 2. Upload Diploma (Storage)
 * 3. Create Profile (Database)
 */
export const registerDietitian = async (data: RegistrationData): Promise<{ success: boolean; error?: string }> => {
  try {
    // 1. Sign Up in Supabase Auth
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email: data.email,
      password: data.password,
      options: {
        data: {
          first_name: data.firstName,
          last_name: data.lastName,
        }
      }
    });

    if (authError) throw authError;
    if (!authData.user) throw new Error('User creation failed');

    const userId = authData.user.id;

    // 2. Upload Diploma Image
    const fileExt = data.diplomaFile.name.split('.').pop();
    const fileName = `diplomas/${userId}/diploma-${Date.now()}.${fileExt}`;

    const { error: uploadError } = await supabase.storage
      .from('dietitian-diplomas')
      .upload(fileName, data.diplomaFile);

    if (uploadError) throw uploadError;

    // Get Public URL
    const { data: { publicUrl } } = supabase.storage
      .from('dietitian-diplomas')
      .getPublicUrl(fileName);

    // 3. Insert into 'dietitians' table
    const profileData: DietitianProfile = {
      auth_user_id: userId,
      first_name: data.firstName,
      last_name: data.lastName,
      email: data.email,
      phone: data.phone,
      university: data.university,
      graduation_year: parseInt(data.graduationYear),
      experience_years: parseInt(data.experienceYears),
      specialization: data.specialization,
      bio: data.bio,
      diploma_url: publicUrl
    };

    const { error: dbError } = await supabase
      .from('dietitians')
      .insert([profileData]);

    if (dbError) throw dbError;

    return { success: true };

  } catch (error: any) {
    console.error('Registration error:', error);
    return { success: false, error: error.message || 'Bir hata oluştu.' };
  }
};

/**
 * Fetch the profile of the currently logged-in dietitian
 */
export const getCurrentDietitianProfile = async (): Promise<DietitianProfile | null> => {
  try {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    const { data, error } = await supabase
      .from('dietitians')
      .select('*')
      .eq('auth_user_id', user.id)
      .single();

    if (error) throw error;
    return data;
  } catch (error) {
    console.error('Error fetching profile:', error);
    return null;
  }
};

/**
 * Update Dietitian Profile
 */
export const updateDietitianProfile = async (updates: Partial<DietitianProfile>): Promise<{ success: boolean; error?: string }> => {
  try {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Not authenticated");

    const { error } = await supabase
      .from('dietitians')
      .update(updates)
      .eq('auth_user_id', user.id);

    if (error) throw error;
    return { success: true };
  } catch (error: any) {
    console.error('Update error:', error);
    return { success: false, error: error.message };
  }
};

