const RegisterPage = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    password: '',
    passwordConfirm: '',
    university: '',
    graduationYear: '',
    experienceYears: '',
    specialization: '',
    bio: '',
    isConfirmed: false
  });

  const [diplomaFile, setDiplomaFile] = useState<File | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData(prev => ({ ...prev, isConfirmed: e.target.checked }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setError(null);
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Client-side Validation
      const maxSize = 5 * 1024 * 1024; // 5MB
      if (file.size > maxSize) {
        setError("Dosya boyutu 5MB'dan büyük olamaz.");
        e.target.value = ''; // Reset input
        setDiplomaFile(null);
        return;
      }

      if (!file.type.startsWith('image/')) {
        setError("Lütfen geçerli bir resim dosyası (JPG, PNG) yükleyiniz.");
        e.target.value = ''; // Reset input
        setDiplomaFile(null);
        return;
      }

      setDiplomaFile(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Validation
    if (formData.password !== formData.passwordConfirm) {
      setError("Şifreler eşleşmiyor.");
      return;
    }
    if (!formData.isConfirmed) {
      setError("Lütfen lisanslı diyetisyen olduğunuzu onaylayın.");
      return;
    }
    if (!diplomaFile) {
      setError("Lütfen diplomanızı yükleyin.");
      return;
    }

    setLoading(true);

    const payload: RegistrationData = {
      email: formData.email,
      password: formData.password,
      firstName: formData.firstName,
      lastName: formData.lastName,
      phone: formData.phone,
      university: formData.university,
      graduationYear: formData.graduationYear,
      experienceYears: formData.experienceYears,
      specialization: formData.specialization,
      bio: formData.bio,
      diplomaFile: diplomaFile
    };

    const result = await registerDietitian(payload);

    if (result.success) {
      // Navigate to profile or dashboard after success
      navigate('/profile'); 
    } else {
      setError(result.error || "Kayıt sırasında bir hata oluştu.");
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-emerald-50 to-teal-50 py-12 px-4 sm:px-6 lg:px-8">
