              <span>{error}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-8">

            {/* Personal Info Section */}
            <div>
              <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
