import { supabase } from '../../../lib/supabaseClient';
import { Appointment } from '../../../shared/types';
import { APPOINTMENTS } from '../../../shared/constants';

/**
 * Fetch all appointments for the logged-in dietitian
 */
export const fetchAppointments = async (): Promise<Appointment[]> => {
  try {
    const { data, error } = await supabase
      .from('appointments')
      .select(`
        *,
        clients:client_id (
          full_name,
          avatar_url
        )
      `)
      .order('date', { ascending: true });

    if (error) {
      console.warn('Supabase fetch error, using mock data:', error.message);
      return getMockAppointments();
    }

    if (!data || data.length === 0) {
      return getMockAppointments();
    }

    return data.map((item: any) => ({
      id: item.id,
      clientId: item.client_id,
      clientName: item.clients?.full_name || 'Bilinmeyen Danışan',
      clientAvatar: item.clients?.avatar_url,
      title: item.title,
      date: item.date,
      time: item.time,
      duration: item.duration,
      type: item.type,
      status: item.status,
    }));
  } catch (err: any) {
    console.warn('Network error in fetchAppointments, using fallback:', err.message || err);
    return getMockAppointments();
  }
};

/**
 * Helper to get initial mock data formatted correctly
 */
const getMockAppointments = (): Appointment[] => {
  const today = new Date().toISOString().split('T')[0];
  return APPOINTMENTS.map((apt, index) => ({
    ...apt,
    date: today,
    clientId: (index + 1).toString(),
    id: `mock-${index}`
  }));
};

/**
 * Create a new appointment
 */
export const createAppointment = async (appointment: Appointment): Promise<Appointment | null> => {
  try {
    const { data: { user } } = await supabase.auth.getUser();

    const payload = {
      client_id: appointment.clientId,
      title: appointment.title,
      date: appointment.date,
      time: appointment.time,
      duration: appointment.duration,
      type: appointment.type,
      status: 'upcoming',
      dietitian_id: user?.id 
    };

    const { data, error } = await supabase
      .from('appointments')
      .insert([payload])
      .select(`
        *,
        clients:client_id (
          full_name,
          avatar_url
        )
      `)
      .single();

    if (error) {
      console.error('Error creating appointment:', error);
      throw error;
    }

    return {
      id: data.id,
      clientId: data.client_id,
      clientName: data.clients?.full_name || appointment.clientName,
      clientAvatar: data.clients?.avatar_url || appointment.clientAvatar,
      title: data.title,
      date: data.date,
      time: data.time,
      duration: data.duration,
      type: data.type,
      status: data.status,
    };
  } catch (err) {
    console.error('Create appointment exception:', err);
    return null;
  }
};

/**
 * Delete an appointment
 */
export const deleteAppointmentService = async (id: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('appointments')
      .delete()
      .eq('id', id);

    if (error) {
      console.error('Error deleting appointment:', error);
      return false;
    }
    return true;
  } catch (err) {
    console.error('Delete appointment exception:', err);
    return false;
  }
};

