  const handleRecipeSelect = (recipe: Recipe) => {
    if (!activeCell) return;

    setWeeklyPlan(prev => ({
      ...prev,
      [activeCell.day]: {
        ...(prev[activeCell.day] || {}),
        [activeCell.mealId]: recipe
      }
    }));
